 const periods=reports.map((report,index)=>{const other=reports[1-index],unavailable=report.coverage.status==='unavailable';return{range:report.range,coverage:report.coverage,identityCoverage:{identifiedPageViews:report.measurement.identifiedPageViews,unidentifiedPageViews:report.measurement.unidentifiedPageViews},totalGroups:unavailable?null:rows[index].length,returnedGroups:rows[index].length,returnedPageViews:unavailable?null:rows[index].reduce((n,row)=>n+row.pageViews,0),truncated:false,rows:rows[index].map(row=>{const found=rows[1-index].find(value=>JSON.stringify(value.key)===JSON.stringify(row.key)),keyed=field!=='event'&&(other.measurement.identifiedPageViews??0)>0,counterpart=other.coverage.status==='unavailable'?{...Object.fromEntries(names.map(name=>[name,null])),present:null}:found?{...Object.fromEntries(names.map(name=>[name,found[name]])),present:true}:{pageViews:0,customEvents:0,identifiedPageViews:0,visitors:keyed?0:null,visits:keyed?0:null,bounceRate:null,averageVisitSeconds:null,present:false};const metric=field==='event'?'customEvents':'visitors',current=index?counterpart[metric]:row[metric],previous=index?row[metric]:counterpart[metric],absolute=report.coverage.status==='complete'&&other.coverage.status==='complete'&&current!==null&&previous!==null?current-previous:null;return{...row,counterpart,change:{absolute,percent:absolute!==null&&previous>0?100*absolute/previous:null}};})};});
